'''直接定义一个mask每次左移并与n比对，如果不为1说明有一个1，由于n是无符号整型，所以总共32位'''
class Solution:
    def hammingWeight(self, n: int) -> int:
        bits = 0
        mask = 1
        for i in range(32):
            if n & mask != 0:
                bits+=1
            mask <<= 1
        return bits
