//Editorial: Going to every bit and check whether its set or not.
class Solution {
public:
    int hammingWeight(uint32_t n) {
        int ans=0;
        for(int i=0;i<32;i++)
        {
            if(n&(1<<i))
                ans+=1;
        }
        return ans;
    }
};

